with flagged as (select *, case when paid_at - lag(paid_at) over (partition by status order by paid_at, id) > interval '60' day then 1 else 0 end as session_start_flag from payments), sessionized as (select *, sum(session_start_flag) over (partition by status order by paid_at, id rows between unbounded preceding and current row) as island_id from flagged) select id, amount, paid_at, status, session_start_flag, island_id, case when status rlike '^(SUCCESS|FAILED)$' then 'GROUP_A' when status rlike '^(REFUNDED)$' then 'CORE' else 'OTHER_ZONE' end as status_zone from sessionized order by status_zone desc, status desc;
